// ── Funciones de localización offline ───────────────

/**
 * Distancia Haversine en km entre dos puntos lat/lng
 */
function haversineKm(lat1,lon1,lat2,lon2){
  const R=6371,dLat=(lat2-lat1)*Math.PI/180,dLon=(lon2-lon1)*Math.PI/180;
  const a=Math.sin(dLat/2)**2+Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*Math.sin(dLon/2)**2;
  return R*2*Math.asin(Math.sqrt(a));
}

/**
 * Encuentra el PK más cercano usando el índice de grid.
 * @param {number} lat
 * @param {number} lng
 * @param {string|null} roadFilter  - buscar solo en esta carretera (null = cualquiera)
 * @param {number} maxKm            - radio máximo de búsqueda en km (default 2)
 * @returns {{road:string, pk:number, distKm:number, lat:number, lng:number}|null}
 */
function findNearestPK(lat, lng, roadFilter=null, maxKm=2) {
  const CELL=0.5;
  const cLat=Math.floor(lat/CELL), cLng=Math.floor(lng/CELL);
  let best=null, bestD=Infinity;

  for(let dl=-1;dl<=1;dl++) {
    for(let dg=-1;dg<=1;dg++) {
      const cands=PK_GRID[`${cLat+dl}:${cLng+dg}`];
      if(!cands) continue;
      for(const [road,pkD,pLat,pLng] of cands) {
        if(roadFilter && road!==roadFilter) continue;
        const d=haversineKm(lat,lng,pLat,pLng);
        if(d<bestD && d<=maxKm){ bestD=d; best={road,pk:pkD,distKm:d,lat:pLat,lng:pLng}; }
      }
    }
  }

  if(!best) return null;

  // Interpolación lineal entre PKs adyacentes para mayor precisión
  const rPKs=PK_SEED[best.road];
  if(rPKs && rPKs.length>1) {
    const idx=rPKs.findIndex(p=>p[0]===best.pk);
    if(idx>0) {
      const [,pLa,pLo]=rPKs[idx-1], [,cLa,cLo]=rPKs[idx];
      const segLen=haversineKm(pLa,pLo,cLa,cLo);
      if(segLen>0) {
        const distToPrev=haversineKm(lat,lng,pLa,pLo);
        const frac=Math.min(1,distToPrev/segLen);
        const pkPrev=rPKs[idx-1][0], pkCurr=rPKs[idx][0];
        best.pk=Math.round((pkPrev+(pkCurr-pkPrev)*frac)*1000)/1000;
      }
    }
  }

  return best;
}

/**
 * Formatea PK decimal a string "PK 12+500"
 * @param {number} pkDecimal
 * @returns {string}
 */
function formatPK(pkDecimal) {
  const km=Math.floor(pkDecimal);
  const m=Math.round((pkDecimal-km)*1000);
  return `PK ${km}+${String(m).padStart(3,'0')}`;
}

/** Lista de carreteras disponibles en el dataset */
const ROAD_LIST = Object.keys(PK_SEED).sort();

